[CmdletBinding()]param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path,[string]$ReportPath='ES/Output/StaticReplay/es-abcd-risk-routing.json')
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDAuditGate.psm1') -Force;$l=Get-ESABCDValidationProfile low;$c=Get-ESABCDValidationProfile critical;$cases=@([pscustomobject]@{case='low-risk-minimal-path';status=if($l.skipFullTraversal -and -not$l.requiresFinalGate -and $l.profile.maxReads -lt 5){'passed'}else{'failed'}},[pscustomobject]@{case='critical-deep-final-gate';status=if($c.profile.deepAudit -and $c.requiresFinalGate -and $c.profile.maxBranches -ge 5){'passed'}else{'failed'}},[pscustomobject]@{case='risk-separation';status=if($l.profile.mode -ne $c.profile.mode){'passed'}else{'failed'}});$failed=@($cases|Where-Object {$_.status -eq 'failed'});$overall='passed';if($failed.Count){$overall='failed'};$refs=@('ES/Automation/ABCD/ESABCDAuditGate.psm1','ES/Automation/ABCD/Test-ESABCDRiskRouting.ps1');$hashes=[ordered]@{};foreach($ref in $refs){$hashes[$ref]=(Get-FileHash (Join-Path $root $ref) -Algorithm SHA256).Hash.ToLowerInvariant()};$report=[ordered]@{schemaVersion=1;validator='Test-ESABCDRiskRouting';status=$overall;staticStatus=if($failed.Count){'static-failed'}else{'static-passed'};runtimeStatus='runtime-not-run';evidenceLevel='S1';capturedUtc=[DateTime]::UtcNow.ToString('o');caseCount=$cases.Count;passedCount=($cases.Count-$failed.Count);failedCount=$failed.Count;cases=$cases;authorizationKind='read-only';sourceRefs=$refs;sourceRefHashes=$hashes;evidenceContractId='es.skill-evidence-receipt';evidenceContractHash=(Get-FileHash (Join-Path $root 'ES/Automation/Contracts/es-skill-evidence-receipt-v1.schema.json') -Algorithm SHA256).Hash.ToLowerInvariant();skillName='es-agent-mechanism-replication';case='abcd-risk-routing';toolId='es-abcd-risk-routing-validator';receiptPath=$ReportPath.Replace('\','/');unityVersion='not-run';claimsNotProven=@('risk classifier completeness')};$out=Join-Path $root $ReportPath;New-Item -ItemType Directory -Force (Split-Path $out)|Out-Null;[IO.File]::WriteAllText($out,($report|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$report|ConvertTo-Json -Depth 20;if($failed.Count){exit 1}
